function makeCase(id,victim,culprit,method,narrative,timeline,clues,suspects,config={}){
 const type=config.type||'murder';
 const subject=config.subject||{kind:'victim',name:victim,label:victim};
 const solution={responsibleCharacter:culprit,revealPhrase:config.revealPhrase||(type==='murder'?'killed '+victim:'resolved the mystery'),method,narrative};
 const title=config.title||(type==='murder'?'The death of '+victim:'Untitled mystery');
 const resolutionPrompt=config.resolutionPrompt||(type==='murder'?'Who killed '+victim+'?':'Who is responsible?');
 return {id,type,title,resolutionPrompt,subject,solution,timeline,clues,suspects:suspects.map(s=>({name:s[0],title:s[1],role:s[0]===solution.responsibleCharacter?'CULPRIT':'INNOCENT',motive:s[2],alibi:s[3],statement:s[4],clue:s[5],secret:s[6]})),scoring:{correctVote:3,culpritEscape:2,statement:1}};
}
